import subprocess
import os
import time
import glob

def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    subprocess.Popen(['Rscript', r_script_path])

    start_time = time.time()
    while time.time() - start_time < duration:
        if glob.glob(output_path):
            return (True, 'File generated successfully within the specified duration.')
        time.sleep(0.1)

    return (False, 'File not generated within the specified duration.')

import subprocess
import platform
import time

def task_func(url):
    system = platform.system()
    if system == "Windows":
        process = subprocess.Popen(['cmd', '/c', 'start', url])
    elif system == "Darwin":
        process = subprocess.Popen(['open', url])
    else:
        process = subprocess.Popen(['xdg-open', url])

    return code if (code := process.wait()) is not None else 0

import subprocess
import os
import random

def task_func(directory, file_list):
    if not file_list:
        return None

    filename = random.choice(file_list)
    file_path = os.path.join(directory, filename)

    try:
        process = subprocess.Popen(file_path)
        return process.poll()
    except Exception:
        return None

import subprocess
import pandas as pd
import matplotlib.pyplot as plt
import sys

def task_func(script_path, output_file_path):
    try:
        subprocess.run([sys.executable, script_path], check=True)
    except Exception:
        raise ValueError("Script execution failed")

    try:
        df = pd.read_csv(output_file_path)
    except Exception:
        raise ValueError("Invalid CSV file")

    if df.shape[1] != 2:
        raise ValueError("CSV does not contain exactly 2 columns")

    ax = df.plot.bar(x=df.columns[0], y=df.columns[1])
    return df, ax

import subprocess
import logging
import os

def task_func(filepath):
    if not os.path.exists(filepath):
        logging.error(f"File not found: {filepath}")
        raise FileNotFoundError(f"The file {filepath} does not exist.")

    try:
        subprocess.run(['g++', filepath], check=True, capture_output=True, text=True)
        logging.info(f"Compilation successful for {filepath}")
    except subprocess.CalledProcessError as e:
        logging.error(f"Compilation failed for {filepath}: {e.stderr}")
        raise e
    except FileNotFoundError as e:
        logging.error("Compiler 'g++' not found.")
        raise e

import subprocess
import os
import glob
# Constants
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR)

    files = glob.glob(pattern)
    archive_path = os.path.join(ARCHIVE_DIR, 'archive.tar.gz')

    if files:
        subprocess.run(['tar', '-czf', archive_path] + files)
        for file in files:
            if os.path.isfile(file):
                os.remove(file)

    return archive_path
